searchData={"items":[{"type":"module","title":"DevSupport","doc":"","ref":"DevSupport.html"},{"type":"function","title":"DevSupport.drop_database/2","doc":"","ref":"DevSupport.html#drop_database/2"},{"type":"function","title":"DevSupport.get_datastore_options/1","doc":"","ref":"DevSupport.html#get_datastore_options/1"},{"type":"function","title":"DevSupport.load_database/2","doc":"","ref":"DevSupport.html#load_database/2"},{"type":"function","title":"DevSupport.start_dev_environment/1","doc":"","ref":"DevSupport.html#start_dev_environment/1"},{"type":"function","title":"DevSupport.stop_dev_environment/0","doc":"","ref":"DevSupport.html#stop_dev_environment/0"},{"type":"module","title":"MscmpSystMcpPerms.Types.AccessAccountPermsSelector","doc":"Defines the Access Account selector for globally applicable MCP permissions.","ref":"MscmpSystMcpPerms.Types.AccessAccountPermsSelector.html"},{"type":"type","title":"MscmpSystMcpPerms.Types.AccessAccountPermsSelector.t/0","doc":"Defines the Access Account selector for globally applicable MCP permissions.","ref":"MscmpSystMcpPerms.Types.AccessAccountPermsSelector.html#t:t/0"},{"type":"type","title":"Attributes - MscmpSystMcpPerms.Types.AccessAccountPermsSelector.t/0","doc":"* `access_account_id` - the record ID of the Access Account which is the\n  subject of Permissions related actions.","ref":"MscmpSystMcpPerms.Types.AccessAccountPermsSelector.html#t:t/0-attributes"},{"type":"module","title":"Msdata.SystAccessAccountPermRoleAssigns","doc":"Definition of a system/application permission.\n\nDefined in `MscmpSystMcpPerms`.","ref":"Msdata.SystAccessAccountPermRoleAssigns.html"},{"type":"type","title":"Msdata.SystAccessAccountPermRoleAssigns.t/0","doc":"","ref":"Msdata.SystAccessAccountPermRoleAssigns.html#t:t/0"},{"type":"function","title":"Msdata.SystAccessAccountPermRoleAssigns.insert_changeset/1","doc":"Creates a validated `Ecto.Changeset` struct for inserting into the database.","ref":"Msdata.SystAccessAccountPermRoleAssigns.html#insert_changeset/1"},{"type":"function","title":"Parameters - Msdata.SystAccessAccountPermRoleAssigns.insert_changeset/1","doc":"* `insert_params` - the initial values with which to populate the new\n    record.","ref":"Msdata.SystAccessAccountPermRoleAssigns.html#insert_changeset/1-parameters"},{"type":"module","title":"MscmpSystMcpPerms","doc":"Implements `MscmpSystPerms` related functionality for the `MssubMcp` subsystem.\n\nThe only public API provided by this module are the selector structs which are\nused to identify the user context of various Permission related actions. These\nstructs implement the `MscmpSystPerms.Protocol` and are usable via the\nPermissions Protocol API at `MscmpSystPerms`.\n\nFor more complete information about Permissions, see the `MscmpSystPerms`\ncomponent documentation.\n\n<!-- MDESC !-->\n\nThe currently defined structs are:\n\n  * `t:MscmpSystMcpPerms.Types.AccessAccountPermsSelector.t/0`","ref":"MscmpSystMcpPerms.html"},{"type":"module","title":"MscmpSystMcpPerms.Types","doc":"Types used by the MCP Perms component.","ref":"MscmpSystMcpPerms.Types.html"},{"type":"type","title":"MscmpSystMcpPerms.Types.access_account_perm_role_params/0","doc":"A map defining the data elements required for creating Access Account\nPermission Role Assigns records.","ref":"MscmpSystMcpPerms.Types.html#t:access_account_perm_role_params/0"},{"type":"type","title":"Attributes - MscmpSystMcpPerms.Types.access_account_perm_role_params/0","doc":"* `access_account_id` - the record ID of the Access Account record being\n  granted a Permission Role.\n\n  * `perm_role_id` - the record ID of the Permission Role which is to be\n  granted to the identified Access Account.","ref":"MscmpSystMcpPerms.Types.html#t:access_account_perm_role_params/0-attributes"}],"proglang":"elixir","content_type":"text/markdown","producer":{"name":"ex_doc","version":"0.38.4"}}